	public void save_lat_qual_state() {
		(this.@nodes).save_lat_qual_state();
		(this.@links).save_qual_state();
	}

	public void save_hyd_state() {
		(this.@nodes).save_hyd_state();
		(this.@links).save_hyd_state();
	}

	public void reset_state() {
		this.@runtime_coupling_used = false;
		(this.@nodes).reset_state();
		(this.@links).reset_state();
		(this.@subcatches).reset_state();
		(this.@gages).reset_state();
		(this.@tables).reset_cursors();
		this.@current_time = 0.0d;
		this.@current_date = (this.@options).@start_date;
		this.@dt_controls_remaining = 0.0d;
		this.@elapsed_ms = 0.0d;
		this.@old_elapsed_ms = 0.0d;
		this.@next_report_ms = (1000.0d * (this.@options).@report_step);
	}

	public void shrink_all_to_fit() {
		(this.@nodes).shrink_to_fit();
		(this.@links).shrink_to_fit();
		(this.@subcatches).shrink_to_fit();
		(this.@gages).shrink_to_fit();
		(this.@pollutants).shrink_to_fit();
		(this.@landuses).shrink_to_fit();
		(this.@buildup).shrink_to_fit();
		(this.@washoff).shrink_to_fit();
		(this.@treatment).shrink_to_fit();
		(this.@spatial).shrink_to_fit();
	}

	public int n_nodes() {
		return (this.@node_names).size();
	}

	public int n_links() {
		return (this.@link_names).size();
	}

	public int n_subcatches() {
		return (this.@subcatch_names).size();
	}

	public int n_gages() {
		return (this.@gage_names).size();
	}

	public int n_pollutants() {
		return (this.@pollutant_names).size();
	}

	public int n_landuses() {
		return (this.@landuse_names).size();
	}

	public int n_tables() {
		return ((int) (this.@tables).count());
	}

	public int find_timeseries(cpp.Str name) {
		return (this.@tables).find_by_kind(name.Clone(), true);
	}

	public int find_curve(cpp.Str name) {
		return (this.@tables).find_by_kind(name.Clone(), false);
	}

